{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the change in the Consumer Price Index over the most recent 12 months; if the CPI is negative, no increase is allowed.","key_value":"lower of 3% per year or 80% of CPI; 0% if CPI negative","coverage_conditions":"Residential rent increases in the city; does not apply to residential buildings constructed after February 1, 1995, or mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Mobile home spaces offered for rent after January 1, 1990 are also outside the cap."},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance requirement","requirement":"After 30 days of tenancy an owner may not terminate a tenancy without just cause, which must be stated in a written notice; before a just cause termination notice the owner must first give the tenant notice of the violation and time to fix it.","key_value":"just cause required after 30 days","coverage_conditions":"Residential tenancies of more than 30 days; does not apply to housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories, and other shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Excludes housing produced in the last 15 years (relative period; anchor date not stated in text)"},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; other shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana no-fault just cause relocation assistance","requirement":"Where a tenancy is terminated for no-fault just cause, the owner must either provide three months of relocation assistance or waive rent for the final three months of the tenancy.","key_value":"3 months' relocation assistance or 3 months' rent waived","coverage_conditions":"Residential tenancies covered by the Just Cause Eviction Ordinance that are terminated for a no-fault just cause.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"Under a no-fault just cause termination, the owner shall either provide 3 months of relocation assistance or waive payment of rent for the final 3 months of the tenancy.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
